```json
{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "network_delay",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, round(approx_quantile(c.duration,0.5)/1e6,1) client_p50_ms, round(approx_quantile(s.duration,0.5)/1e6,2) server_p50_ms, round(approx_quantile(c.duration - s.duration,0.5)/1e6,1) gap_p50_ms FROM abnormal_traces c JOIN abnormal_traces s ON c.trace_id = s.trace_id AND s.parent_span_id = c.span_id WHERE c.attr_span_kind='Client' AND s.attr_span_kind='Server' GROUP BY 1,2 ORDER BY gap_p50_ms DESC",
          "claim": "search→rate client calls take about 1662 ms p50 while rate server spans take 0.08 ms; the gap is on the wire."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, round(approx_quantile(duration,0.5)/1e6,1) p50, round(approx_quantile(duration,0.95)/1e6,1) p95 FROM abnormal_traces WHERE span_name IN ('rate.Rate/GetRates','search.Search/Nearby','geo.Geo/Nearby') GROUP BY 1,2,3 ORDER BY 1,2,3",
          "claim": "Search's calls to geo stay at 0.5 ms while its calls to rate rise to 2205 ms p95 with rate server time flat."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='rate' AND attr_span_kind='Server' GROUP BY 1",
          "claim": "rate's own server-side GetRates span p95 is 1.2 ms in the abnormal window, below its normal 1.6 ms."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "rate",
      "to": "search",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, round(approx_quantile(c.duration,0.5)/1e6,1) client_p50_ms, round(approx_quantile(s.duration,0.5)/1e6,2) server_p50_ms FROM abnormal_traces c JOIN abnormal_traces s ON c.trace_id = s.trace_id AND s.parent_span_id = c.span_id WHERE c.attr_span_kind='Client' AND s.attr_span_kind='Server' AND c.service_name='search' GROUP BY 1,2",
          "claim": "Search's server span p50 (1733 ms) tracks its slow outgoing call to rate (1732 ms), so latency is inherited from rate."
        }
      ]
    },
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, round(approx_quantile(c.duration,0.5)/1e6,1) client_p50_ms, round(approx_quantile(s.duration,0.5)/1e6,1) server_p50_ms FROM abnormal_traces c JOIN abnormal_traces s ON c.trace_id = s.trace_id AND s.parent_span_id = c.span_id WHERE c.attr_span_kind='Client' AND s.attr_span_kind='Server' AND c.service_name='frontend' AND s.service_name='search' GROUP BY 1,2",
          "claim": "Frontend's calls to search take about 1726 ms p50, matching search's server time; the delay passes up to frontend."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) n, round(approx_quantile(duration,0.5)/1e6,1) p50, round(approx_quantile(duration,0.95)/1e6,1) p95 FROM abnormal_traces WHERE service_name='frontend' AND attr_span_kind='Server' GROUP BY 1 ORDER BY p95 DESC",
          "claim": "Only the frontend /hotels path (which calls search) is slow, at about 2193 ms p95; other paths stay near 1–2 ms."
        }
      ]
    }
  ]
}
